INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40724, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, would you look at that, perhaps you\'re as good as killing apes as O\'ggon!', 0),
(40725, 0, 0, 0, 0, 0, 0, 0, 0, 'Well would you look at that, you got the claws. As much as I hate to see money go away, it needs to be done, here.', 0),
(40726, 0, 0, 0, 0, 0, 0, 0, 0, 'Would you look at that, perfect size too. Thanks a bunch!', 0),
(40727, 0, 0, 0, 0, 0, 0, 0, 0, 'Why, this is it! I\'ll be honest with you, I thought the apes would tear you apart when you trundled out of here, but to actually have it in my hands...$B$BHere, take this ring. I\'m trying to save gold just in case this Tel Co. thing goes even more pear-shaped.', 0),
(40728, 0, 0, 0, 0, 0, 0, 0, 0, 'Maybe we stand a chance after all! You really took the fight to them, you might of even made O\'ggon jealous.$B$BNice work out there, here, as a thanks from us here at Tel Co.', 0),
(40729, 0, 0, 0, 0, 0, 0, 0, 0, 'These should do. You have aided my experiments.', 0),
(40730, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, here we go... Maybe it really is this simple.', 0),
(40731, 0, 0, 0, 0, 0, 0, 0, 0, 'Tazzo sent you huh? He\'s finally coming back crawling for that information. He made such a point about being able to figure it out all on his own, and here he is, sending a mule to do his dirty work.$B$B<Leezza begins to laugh.>$B$BThat is almost as insulting as his stupidly big head wandering here and asking himself.$B$BLook $C, you want that info, it\'ll cost you, lets make it one gold, fifty silver, and a favor afterwards while you\'re here.', 0),
(40732, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, about time.', 0),
(40733, 0, 0, 0, 0, 0, 0, 0, 0, 'So, her rumors -were- true!$B$BThe secrets of the Gargantuan Banana were real!', 0),
(40734, 0, 0, 0, 0, 0, 0, 0, 0, 'It\'s... It\'s...$B$B<Tazzo is lost for words, his face a mix of wonder, and amazement as he takes his time to study the banana. Placing a single hand upon the skin, the gnome would gently pat it.>$B$BBeautiful.', 0),
(40735, 0, 0, 0, 0, 0, 0, 0, 0, 'My my, you are resourceful!$B$BI could probably tell you to go and get me the head of Illidan, and you\'d be back in a couple days!$B$BNow now, lets get to it..', 0),
(40736, 0, 0, 0, 0, 0, 0, 0, 0, 'Brilliant, I will make sure to put them to good use.', 0),
(40737, 0, 0, 0, 0, 0, 0, 0, 0, 'We did it $N, with my powers, and your handiness we figured out the secret to the Gargantuan Banana. I never thought I would see the day where I could pull something off like this!$B$BI have you to thank for this, without you, I\'d still be here fiddling with bananas and putting giant elixirs on them if I was lucky.$B$BFrom now on, if you ever need another Gargantuan Tel\'abim Banana, you come here, and I\'ll make one, should you have the materials of course!', 0),
(40738, 0, 0, 0, 0, 0, 0, 0, 0, 'What is this thing, it\'s massive! Such a unique texture, this is one of those gargantuan bananas that Tazzo has been going on about, he finally did it?$B$B<The goblin smirks from ear to ear.>$B$BWith this thing I could become a legend back at Kezan. Say, why don\'t you help me develop some recipes? You help me, and I\'ll even share. With my name on them of course.', 0),
(40739, 0, 0, 0, 0, 0, 0, 0, 0, '<Within a matter of seconds, the gnome processes the bananas and procures a Gargantuan Bananas before your eyes.>$B$BThere you have it, one transmuted Gargantuan Banana. If you ever want more bananas, stop by any time!', 0),
(40740, 0, 0, 0, 0, 0, 0, 0, 0, '<Within a matter of seconds, the gnome processes the bananas and procures five Gargantuan Bananas before your eyes.>$B$BSee? It\'s all refined now! If you ever want more bananas, stop by any time!', 0),
(40741, 0, 0, 0, 0, 0, 0, 0, 0, '<A massive sigh of relief escapes from Baron Telraz>$B$BOh my, you just saved my day, and my company at that! I was seriously -FREAKING OUT- here, and you went and got this all done for me.$B$BHere, I pay those that help and save my hide. You can take this gold coin from me-a gesture of good will.', 0),
(40742, 0, 0, 0, 0, 0, 0, 0, 0, 'Heh, those pesky Brushtails never bothered me any, maybe the workers will be able to finally get back to work with less danger out there.$B$BThanks for the work, here, as a reward, we have a bunch of extra stuff laying around these days.', 0),
(40752, 0, 0, 0, 0, 0, 0, 0, 0, 'Here it is, a magical delicacy for fresh minds!$B$BI present Danonzo\'s Tel\'Abim Surprise, just like its name implies, a sheer treat to the tongue. A mix of both chewy and sweet textures served warm with a sheer lovely taste. Thanks to the garnish of Heart of the Wild.$B$BAs I promised, here is the recipe. Don\'t forget to tell people who figured this all out now, ya\'hear?', 0),
(40753, 0, 0, 0, 0, 0, 0, 0, 0, 'Here it is, a magical delicacy for fresh minds!$B$BI present Danonzo\'s Tel\'Abim Delight, just like its name implies, a sheer treat to the tongue, a mix of bow chewy and sweet textures served warm with a sheer lovely taste thanks to the garnish of Mountain Silversage.$B$BAs I promised, here is the recipe, don\'t forget to tell people who figured this all out now, ya\'hear?', 0),
(40754, 0, 0, 0, 0, 0, 0, 0, 0, 'It is complete, Danonzo\'s Tel\'Abim Medley!$B$BServed cold, this banana cake is filled with a airy banana cream, incredibly sweet, with a crumbly outer layer! With this, I shall dominate Kezan, and potentially even other markets!$B$BI did promise to share this recipe, and I am an honest goblin, perhaps rare for my kind.$B$BJust remember where you got it huh, I don\'t want anyone stealing my ideas now, you know?', 0),
(40755, 0, 0, 0, 0, 0, 0, 0, 0, 'By my ears, this is it! Well done, this has saved me an extraordinary amount of time, and as you know, time is money, especially in this case.', 0),
(40756, 0, 0, 0, 0, 0, 0, 0, 0, 'Huh, what is it you want, you here for something special?$B$BOh, Bixxle sent you huh, that idiot? He spent a good five years making some banana sorter, what does he need?', 0),
(40757, 0, 0, 0, 0, 0, 0, 0, 0, '<Jabbey looks on the small pile of snuff with displeasure.>$B$BWell this certainly is a disappointment.', 0),
(40758, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, I didn\'t expect you to actually return, that\'s a bummer. Oh well, a goblins word means something in this world, to some people anyway.', 0),
(40759, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, they were that hard to get, huh? Hope it wasn\'t too much of a fuss getting them for me. Here, take some coin for all the trouble.', 0),
(40760, 0, 0, 0, 0, 0, 0, 0, 0, '<Bixxle let\'s out a sigh of relief, smirking from ear to ear.>$B$BYou\'ve really helped me out here, working from Tel\'Abim complicates everything, especially with how remote the location is.$B$BYou came in clutch friend, and for that I should reward you with something, and I know just the thing.$B$BLook, if you ever need anything else, let me know, you\'ve saved me more gold than I would\'ve made in years, and almost as much time even!', 0),
(40761, 0, 0, 0, 0, 0, 0, 0, 0, 'I assume he complained huh?$B$B<Bixxle laughs.>$B$BYeah, this is quite secretive and a prototype build of Dark Iron Engineers, that\'s why we\'re going to master it.$B$BYou wouldn\'t imagine it but I am quite a reknowned Engineer, and have had many run ins with these \'Dark Irons\', heck I was even contracted for some stuff in their vaunted city.', 0),
(40762, 0, 0, 0, 0, 0, 0, 0, 0, 'Behold, a creation of great magnitude, the ideas of wicked dwarven design, crafted by yours truly.$B$BI hope this serves you well, and does what damage you need to deal on those that may be your enemy.$B$BWe are even now, this surely is worth quite a bit of gold after all, maybe not as much as my Screwfuse 1000, but close enough.$B$BBest of luck out there $N, I hope we cross paths again.', 0),
(40763, 0, 0, 0, 0, 0, 0, 0, 0, 'This is a nice haul and the ghosts are gone, yeah? I will order the crew to start diggin\' once we make sure there\'s no further complications. Now let\'s see about these texts... Hmm, very fascinating! $R I may need your assistance again.', 0),
(40764, 0, 0, 0, 0, 0, 0, 0, 0, 'Hoo mama! This is what I\'m talkin\' about! This haul will earn us lots of prestige and accolades. This is both Azotha, Troll, and  gold from other civilizations they must have buried here! You deserve your share for sure! We may work again in the future, you\'ve certainly been useful!', 0),
(40765, 0, 0, 0, 0, 0, 0, 0, 0, 'Huh, Telraz sent you? I was wondering when he would check in. I guess everything has gotten quite crazy around here after all!', 0),
(40766, 0, 0, 0, 0, 0, 0, 0, 0, 'A report from Bixxle himself? Give me that!$B$B<Baron Telraz frantically reads the letter with utmost curiosity, letting out a sigh of relief.>$B$BMy, that certainly is a relief! Without Bixxle, I would have no idea how to manage things up there. Thanks for the work kid. Here, take some coins for the hassle of running around.', 0),
(40767, 0, 0, 0, 0, 0, 0, 0, 0, 'My my, you sure are resourceful, I didn\'t expect you to get it done so quick.$B$BHere, take this, we have a bunch of spare ones laying around now that the enforcers took off and left south.', 0),
(40768, 0, 0, 0, 0, 0, 0, 0, 0, 'Not bad, good work out there, making the jungle just a little bit easier to handle is always noble work for us here.$B$BHere, as thanks.', 0),
(40769, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, this certainly is a rarity, while you were gone I thought of a few ideas that could work to incorporate the horn into armor, and I believe I have come up with the perfect idea.$B$BTake this, as a thanks for the assistance!', 0),
(40770, 0, 0, 0, 0, 0, 0, 0, 0, 'You help Ebu!$B$BMonkeys thank you, we thank you yes yes!', 0),
(40771, 0, 0, 0, 0, 0, 0, 0, 0, 'Ebu thank you, ebu give you biggest gift of all.$B$BFrom us here, we thank you for everything!', 0),
(40785, 0, 0, 0, 0, 0, 0, 0, 0, 'My my, that is one MASSIVE monkeys foot, this wouldn\'t be Morogo Thunderfoot\'s rear paw now, would it?$B$B<Sneel Fizzwack blinks at you blankly.>$B$BI never expected anyone to actually claim a reward when we put that bounty board up, nor did I expect anyone to be crazy enough to go through with it!$B$BLook, I can find something, here.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40724, 0, 0, 'The apes can be a savage bunch, I would be careful out in the wild.', 0),
(40725, 0, 0, 'Any luck with those murlocs?', 0),
(40726, 0, 0, 'Had any luck finding the damn thing?', 0),
(40727, 0, 0, 'You find my tools yet, kid?', 0),
(40728, 0, 0, 'What are you waiting for, we don\'t give bonus around here kid.', 0),
(40729, 0, 0, 'The longer you stand around, the longer my work will take, go on now, quick quick!', 0),
(40730, 0, 0, 'So, you end up finding that Elixir?', 0),
(40731, 0, 0, 'Tazzo sent you huh? He\'s finally coming back crawling for that information. He made such a point about being able to figure it out all on his own, and here he is, sending a mule to do his dirty work.$B$B<Leezza begins to laugh.>$B$BThat is almost as insulting as his stupidly big head wandering here and asking himself.$B$BLook $C, you want that info, it\'ll cost you.', 0),
(40732, 0, 0, 'So, mule, you get those sacs yet?', 0),
(40733, 0, 0, 'So, you hear anything?', 0),
(40734, 0, 0, 'So, do you got it?!', 0),
(40735, 0, 0, 'You get those materials yet?', 0),
(40736, 0, 0, 'You get a chance to find everything I need?', 0),
(40737, 0, 0, 'Yes?', 0),
(40738, 0, 0, 'Yes? What is it?', 0),
(40739, 0, 0, '<Within a matter of seconds, the gnome processes the bananas and procures three Gargantuan Bananas before your eyes.>$B$BThere you have it, one transmuted Gargantuan Banana. If you ever want more bananas, stop by any time!>', 0),
(40740, 0, 0, '<Within a matter of seconds, the gnome processes the bananas and procures fifteen Gargantuan Bananas before your eyes.>$B$BSee? It\'s all refined now! If you ever want more bananas, stop by any time!>', 0),
(40741, 0, 0, 'So, you get those bananas?$B$B<Baron Telraz appears to be on edge.>', 0),
(40742, 0, 0, 'Those snakes been dealt with?', 0),
(40752, 0, 0, 'You gather everything yet? I\'m dying for the opportunity to cook wonderous dishes here!', 0),
(40753, 0, 0, 'My destiny is ahead of me, what\'s taking you so long to collect everything?', 0),
(40754, 0, 0, 'I can wait no longer to start, hurry up with gathering what I need!', 0),
(40755, 0, 0, 'So, you have any luck yet $C?', 0),
(40756, 0, 0, 'Yes?', 0),
(40757, 0, 0, 'You find that good for nothing thief, and give him justice yet?$B$BBetter yet, you recover my stuff?', 0),
(40758, 0, 0, 'Careful holding that Blighted Essence when you bring it around here, last thing I want is some super disease in Steamwheedle.', 0),
(40759, 0, 0, 'So, what did Jabbey say?', 0),
(40760, 0, 0, 'You get all those things yet?', 0),
(40761, 0, 0, 'So, you speak with him yet?', 0),
(40762, 0, 0, 'Have any luck recovering the materials yes $N?', 0),
(40763, 0, 0, 'Well, how did it go?', 0),
(40764, 0, 0, 'Well? Don\'t keep me in suspense, did ya do it?', 0),
(40765, 0, 0, 'Yes?', 0),
(40766, 0, 0, 'So, have you heard news from Bixxle\'s Storehouse?', 0),
(40767, 0, 0, 'You got rid of those critters yet?', 0),
(40768, 0, 0, 'Yeah, you get those scales yet kid?', 0),
(40769, 0, 0, 'You had any luck yet, or you here looking for a coat to brave the cold weather?', 0),
(40770, 0, 0, 'You hurt murloc, beat murloc?', 0),
(40771, 0, 0, 'You find Nibu, you save Nibu?', 0),
(40785, 0, 0, 'So, whatcha need bub?', 0);
