INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61111, 0, 0, 'There, fixed up, and in good timing too! Now I just need to make sure everything is stabilized...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66567'),
(61108, 0, 0, 'Ahh, my trusty Arclight Spanner, welcome home to Papa.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66568'),
(61100, 0, 0, 'Such a weird specimen.. Stunted in growth, and lacking the essential nutrition, this certainly won\'t do.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66574'),
(61100, 1, 0, 'Such a magnificent sample, after all this time, right under my nose on the very island! I can\'t thank you enough for getting it.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66578'),
(61101, 0, 0, 'Thanks for everything you\'ve done, this machine has cost me a fortune, and I don\'t have another fortune laying around.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66594'),
(61101, 1, 0, 'Such a magnificent weapon, capable of pure destruction, now rested at your hands. I do hope you use it responsibly, and if you don\'t, it\'s all on you, and has nothing to do with me!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66595'),
(61113, 0, 0, 'Look kid, I may have doubted you at first, and well the entire time you were here, but you got results, and actually dealt with that blasted Morogo for us. It\'s nice to have someone around here that can get their feet down and work for a change! Nice work.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66596'),
(61100, 2, 0, 'Tazzo Gearfire pours the Elixir of Giant Growth over top of the banana.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66575'),
(61100, 3, 0, 'The banana begins to bloat, bits of skin tear to the excessive bloating, all before it slumps, and collapses in on itself.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66576'),
(61100, 4, 0, 'Well that was anti-climactic...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66577'),
(61100, 5, 0, 'With the Dream Dust, I can funnel my energy into the banana to produce results of growth...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66569'),
(61100, 6, 0, 'The Tel\'abim Banana begins to grow from the arcane energy.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66570'),
(61100, 7, 0, 'I\'m doing it! Just a little more!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66571'),
(61100, 8, 0, 'With the added Dream Dust, the growth accelerates, soon becoming a Gargantuan Tel\'abim Banana.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66572'),
(61100, 9, 0, 'We have done it, the secrets of the Gargantuan Banana are unlocked and at our finger tips! Can you believe what we have done today?! For your help, I\'ll make them for you any time, just bring me the required materials, and they are yours.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66573'),
(61116, 0, 0, 'This was a few weeks ago, we used to do operations far in the north, around Bixxle\'s Storehouse, we got a bit ambitious, and set our attentions on the Jagged Isles at the very northern tip of the island.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66579'),
(61116, 1, 0, 'It was on the biggest island there I found this banana, bigger than me! Nestled within a bunch of roots and bushes, I could barely move the thing, and left shortly after I heard the chaos of apes attacking the Storehouse.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66580'),
(61116, 2, 0, 'I wouldn\'t bother looking for it, the Jagged Isles are infested with murlocs, naga, and all other sorts of creatures, it isn\'t worth your time.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66581'),
(60955, 0, 0, 'The Dark Iron Desecrator Plans? I- why... Bah, fine, he is asking a lot here, tell him that all of the favors I owe him are cleared.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66164');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061116, 'What do you want? If I were you, I wouldn\'t be sticking my nose where it didn\'t belong.', 'What do you want? If I were you, I wouldn\'t be sticking my nose where it didn\'t belong.', 1, 0);
