INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060955, 'The desert be rife with opportunities, and chances to gain a little coin. I represent some interests across the ocean that are looking for rare and unique goods.\n\nPerhaps we can help each other out, aye?\n\nOh, and uh, if you\'re looking for some cheddar, I got a bunch of it, they took my letter way too seriously.', 'The desert be rife with opportunities, and chances to gain a little coin. I represent some interests across the ocean that are looking for rare and unique goods.\n\nPerhaps we can help each other out, aye?\n\nOh, and uh, if you\'re looking for some cheddar, I got a bunch of it, they took my letter way too seriously.', 1, 0);
